function validate([num, k]) {
  if (typeof num !== 'string' || num.length < 1 || num.length > 30000) return 'num needs 1 to 30000 digits.';
  if (!/^[0-9]+$/.test(num)) return 'num may contain only the digits 0-9.';
  if (num.length > 1 && num[0] === '0') return 'num must not start with a zero.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k is between 1 and 10^9.';
  return null;
}

