function minInteger(num, k) {
  const n = num.length;
  const positions = Array.from({ length: 10 }, () => []);
  for (let i = 0; i < n; i++) {
    positions[num.charCodeAt(i) - 48].push(i);
  }
  const heads = new Array(10).fill(0);
  const tree = new Array(n + 1).fill(0);
  const movedBefore = (index) => {
    let count = 0;
    for (let i = index; i > 0; i -= i & -i) {
      count += tree[i];
    }
    return count;
  };
  const markMoved = (index) => {
    for (let i = index + 1; i <= n; i += i & -i) {
      tree[i]++;
    }
  };
  const result = [];
  for (let step = 0; step < n; step++) {
    for (let digit = 0; digit <= 9; digit++) {
      if (heads[digit] === positions[digit].length) continue;
      const pos = positions[digit][heads[digit]];
      const cost = pos - movedBefore(pos);
      if (cost <= k) {
        k -= cost;
        result.push(digit);
        markMoved(pos);
        heads[digit]++;
        break;
      }
    }
  }
  return result.join('');
}

