function minInteger(num, k) {
  // Simulate the hint directly: for each slot, find the smallest digit within reach and bubble it forward.
  const digits = num.split('');
  let budget = k;
  for (let start = 0; start < digits.length && budget > 0; start++) {
    let pick = start;
    const last = Math.min(digits.length - 1, start + budget);
    for (let j = start + 1; j <= last; j++) if (digits[j] < digits[pick]) pick = j;
    for (let j = pick; j > start; j--) {
      const t = digits[j]; digits[j] = digits[j - 1]; digits[j - 1] = t;
    }
    budget -= pick - start;
  }
  return digits.join('');
}

