function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(9000, 10000) : int(1, 8);
  // A narrow digit range gives many repeated digits; a wide one gives variety.
  const low = int(0, 4), high = Math.min(9, low + int(1, 9));
  let num = String(int(Math.max(1, low), Math.max(1, high)));
  for (let i = 1; i < n; i++) num += String(int(low, high));
  let k;
  if (size === 'large') {
    const scale = rand();
    k = scale < 0.2 ? 1000000000 : scale < 0.6 ? int(1, 20000) : int(1, 3000000);
  } else {
    k = rand() < 0.15 ? int(20, 1000000000) : int(1, 12);
  }
  return [num, k];
}
